css:
.print-format-container {
  font-family: Arial, sans-serif;
  font-size: 12px;
  margin: 20px;
}

.header {
  display: flex;
  align-items: center;
  margin-bottom: 10px;
}

.left-header {
  width: 40%;
  text-align: center;
}

.right-header {
  width: 60%;
  text-align: left;
}

.logo {
  margin-right: 20px;
}

.logo img {
  height: 120px;
}

.datos-generales {
  margin-bottom: 10px;
  border-bottom: 2px solid black;
  border-top: 2px solid black;
}

.info-complement {
  display: flex;
  justify-content: space-evenly;
  margin-top: 10px;
  margin-bottom: 10px;
}

.datos-medicamentos {
  margin-top: 20px;
}

.lefy {
  text-align: left;
  width: 50%;
}

.right {
  text-align: left;
  width: 50%;
}

.footer {
  position: relative;
  bottom: 0;
  left: 0;
  width: 100%;
  padding: 10px;
  margin-top: 10px;
}

.sign-section {
  text-align: left;
}

.signature {
  display: inline-block;
  text-align: center;
}

table {
  width: 100%;
  border-collapse: collapse;
}

th,
td {
  border: 1px solid black;
  text-align: left;
}

#table-info>tr>td {
  border: none !important;
}

table.table-compact td,
table.table-compact th {
  padding: 2px 4px !important;
  /* súper compacto */
  margin: 0 !important;
  line-height: 1.1 !important;
  vertical-align: top;
}

.info-container {
  width: 100%;
  margin-bottom: 20px;
}

.examenes {
  border: 2px solid black;
  padding: 5px;
  border-radius: 2px;
}

.observaciones {
  text-align: left;
  padding: 5px;
}

.observaciones h4 {
  text-align: center;
}
/* Fuente global */
* {
    font-family: Arial, sans-serif;
    font-size: 12px;
}

/* Contenedor principal */
.print-format-container {
    margin: 10px;
}

/* ---------- HEADER ---------- */
#information-table td {
    vertical-align: middle;
    border: none !important;
    padding: 0 !important;
}

/* Logo flexible */
.logo img {
    max-height: 90px;           /* tamaño máximo para portrait */
    width: auto;
    height: auto;
    max-width: 100%;            /* evita desbordes */
}

/* Título */
h3, h4, h5 {
    margin: 4px 0;
}

/* ---------- TABLAS COMPACTAS ---------- */
table {
    width: 100%;
    border-collapse: collapse;
}

th, td {
    border: 1px solid black;
    padding: 2px 4px;
    font-size: 11px;
    line-height: 1.1;
}

/* tabla de datos generales */
#table-info td {
    border: none !important;
}

/* que la tabla principal NO se rompa */
table.main-table {
    page-break-inside: avoid;
}

/* Evitar cortes feos */
tr {
    page-break-inside: avoid !important;
}

tbody {
    page-break-inside: auto !important;
}

/* Sección compacta arriba */
.datos-generales {
    margin-top: 8px;
    margin-bottom: 8px;
    border-top: 1px solid black;
    border-bottom: 1px solid black;
    padding: 6px 0;
}

/* Información complementaria */
.info-complement td {
    border: none !important;
    padding: 2px 0 !important;
}

/* Firma */
.footer {
    margin-top: 50px;
    text-align: left;
}

.signature {
    text-align: left;
}

/* ------ Ajustes específicos para impresión ------ */
@media print {
    * {
        font-size: 12px;
    }
    .logo img {
        max-height: 70px;   /* reduce en portrait para que no "rompa" el header */
    }
    th, td {
        font-size: 9.5px !important;
        padding: 1px 2px !important;
    }
}
